-- Supabase Schema Teardown. Generated by tools/build_sql.py; edit there, not here.

create table if not exists public.findings (
  sort     int primary key,
  number   text not null,
  headline text not null,
  detail   text not null,
  anchor   text not null   -- in-page id the card links to
);
create table if not exists public.rivals (
  sort           int primary key,
  product        text not null,
  positioning    text not null,
  database_layer text not null,
  repo_created   date not null,
  github_stars   int  not null,
  hn_100_stories int  not null,
  hn_points      int  not null,
  ai_first_pick  int  not null,   -- of 150 "Firebase alternative" answers
  ai_named       int  not null
);
alter table public.findings enable row level security;
drop policy if exists "Public read" on public.findings;
drop policy if exists "Public read" on public.rivals;
create policy "Public read" on public.findings for select to anon, authenticated using (true);
alter table public.rivals enable row level security;
create policy "Public read" on public.rivals for select to anon, authenticated using (true);

